async (page) => {
  const started = new Date().toISOString();
  const results = [];
  const browser = page.context().browser();
  for (const [kind, host] of [['resident','https://ca-resident-demo.happyriver-ace49996.uksouth.azurecontainerapps.io'],['employee','https://ca-cutover-test-demo-api.happyriver-ace49996.uksouth.azurecontainerapps.io']]) {
    const context = await browser.newContext({viewport:{width:1365,height:900}});
    const p = await context.newPage();
    const errors = [], failures = [];
    p.on('console', m => { if(m.type()==='error') errors.push(m.text().replace(/https?:\/\/[^\s]+/g,'[url withheld]')); });
    p.on('pageerror', e => failures.push(e.name));
    try {
      let health = null; const warm = [];
      for(let attempt=0;attempt<5;attempt++) {
        try { const r = await context.request.get(host+'/healthz',{timeout:180000}); health = r.status(); warm.push({status:health}); if(health===200) break; }
        catch(e) { warm.push({error:e.name}); }
        await p.waitForTimeout(5000);
      }
      if(health!==200) throw new Error('Health not ready after retries');
      const response = await p.goto(host+'/',{waitUntil:'domcontentloaded',timeout:180000});
      const viewports = [];
      for(const size of [{width:1365,height:900},{width:390,height:844}]) {
        await p.setViewportSize(size);
        await p.waitForTimeout(500);
        const dom = await p.evaluate(() => ({title:document.title,overflow:document.documentElement.scrollWidth>innerWidth,passwordInputs:document.querySelectorAll('input[type=password]').length,widgetScripts:[...document.scripts].filter(s=>s.src.endsWith('/chat-widget.js')).length,launchers:document.querySelectorAll('.chat-widget-launcher').length,dialogs:document.querySelectorAll('[role=dialog]').length,signInLinks:[...document.querySelectorAll('a')].filter(a=>/sign in/i.test(a.textContent)).length}));
        if(kind==='resident') {
          const launcher = p.locator('.chat-widget-launcher');
          dom.launcherVisible = await launcher.isVisible();
          await launcher.click();
          dom.dialogOpened = await p.getByRole('dialog').isVisible();
          await p.keyboard.press('Escape');
        }
        viewports.push({size,...dom});
      }
      let signIn = null;
      if(kind==='employee') {
        await p.goto(host+'/app',{waitUntil:'domcontentloaded',timeout:180000});
        await p.waitForURL(u=>u.hostname==='login.microsoftonline.com',{timeout:60000});
        const u=new URL(p.url()); signIn={origin:u.origin,path:u.pathname,query:'withheld',noAuthenticationAttempted:true};
      }
      results.push({kind,host,health,warm,publicStatus:response.status(),viewports,signIn,consoleErrorCount:errors.length,consoleErrors:errors,pageErrors:failures});
    } finally { await context.close(); }
  }
  return {started,finished:new Date().toISOString(),results,noCredentialsOrSubmissionOrModel:true};
}
